package frc.robot.shooting.regression;

import edu.wpi.first.math.interpolation.InterpolatingDoubleTreeMap;

// Generated by tools/shooter_sim/shooter_sim.py, calibrated to a real shot (3 m @ 32.5 rps, hood at lowest shooting angle).
// Shooter speeds are drum RPS with kGearing 45/22. Hood is real degrees above home (0 = home, 36:1),
// lowest shooting angle 2.67 (HoodConstants.kMinShootingAngle); raising the hood flattens the shot.
public class LookUpTables {
    public class ScoringVelocityLUT{
        public static final InterpolatingDoubleTreeMap scoringvelocityLUT = new InterpolatingDoubleTreeMap();

        static{
            // closer than ~2.25 m the steepest hood shot is too flat to drop into the hub
            /*
            scoringvelocityLUT.put(2.25, 29.10); // meters, RPS
            scoringvelocityLUT.put(2.5, 30.21); // meters, RPS
            scoringvelocityLUT.put(3.0, 32.32); // meters, RPS
            scoringvelocityLUT.put(3.5, 34.17); // meters, RPS
            scoringvelocityLUT.put(4.0, 36.08); // meters, RPS
            scoringvelocityLUT.put(4.5, 37.92); // meters, RPS
            scoringvelocityLUT.put(5.0, 39.70); // meters, RPS
            scoringvelocityLUT.put(5.5, 41.41); // meters, RPS
            */

            // Modified AST 20261012
            scoringvelocityLUT.put(1.75, 25.00); // meters, RPS
            scoringvelocityLUT.put(2.5, 27.00); // meters, RPS
            scoringvelocityLUT.put(3.0, 29.00); // meters, RPS
            scoringvelocityLUT.put(3.5, 32.00); // meters, RPS
            scoringvelocityLUT.put(4.0, 34.00); // meters, RPS
            scoringvelocityLUT.put(4.5, 36.00); // meters, RPS
            scoringvelocityLUT.put(5.0, 38.00); // meters, RPS
            scoringvelocityLUT.put(5.5, 40.00); // meters, RPS
        }
    }

    public class ScoringHoodLUT{
        public static final InterpolatingDoubleTreeMap scoringhoodLUT = new InterpolatingDoubleTreeMap();

        static{
            // closer than ~2.25 m the steepest hood shot is too flat to drop into the hub
            /*
            scoringhoodLUT.put(2.25, 2.67); // meters, Degrees
            scoringhoodLUT.put(2.5, 2.67); // meters, Degrees
            scoringhoodLUT.put(3.0, 3.67); // meters, Degrees
            scoringhoodLUT.put(3.5, 5.67); // meters, Degrees
            scoringhoodLUT.put(4.0, 6.67); // meters, Degrees
            scoringhoodLUT.put(4.5, 7.67); // meters, Degrees
            scoringhoodLUT.put(5.0, 8.67); // meters, Degrees
            scoringhoodLUT.put(5.5, 9.67); // meters, Degrees
            */
            scoringhoodLUT.put(1.75, 3.0); // meters, Degrees
            scoringhoodLUT.put(2.5, 4.0); // meters, Degrees
            scoringhoodLUT.put(3.0, 5.0); // meters, Degrees
            scoringhoodLUT.put(3.5, 6.0); // meters, Degrees
            scoringhoodLUT.put(4.0, 7.0); // meters, Degrees
            scoringhoodLUT.put(4.5, 10.0); // meters, Degrees
            scoringhoodLUT.put(5.0, 11.0); // meters, Degrees
            scoringhoodLUT.put(5.5, 13.0); // meters, Degrees
        }
    }

    public class NetrualZoneVelocityLUT{
        public static final InterpolatingDoubleTreeMap neturalzonevelocityLUT = new InterpolatingDoubleTreeMap();

        static{
            // 3.0 m would need a lob higher than FERRY_MIN_APEX allows at the steepest hood angle
            neturalzonevelocityLUT.put(4.5, 40.0); // meters, RPS
            neturalzonevelocityLUT.put(6.0, 42.0); // meters, RPS
            neturalzonevelocityLUT.put(7.5, 45.0); // meters, RPS
        }
    }

    public class NeturalZoneHoodLUT{
        public static final InterpolatingDoubleTreeMap neturalzonehoodLUT = new InterpolatingDoubleTreeMap();

        static{
            // 3.0 m would need a lob higher than FERRY_MIN_APEX allows at the steepest hood angle
            neturalzonehoodLUT.put(4.5, 15.0); // meters, Degrees
            neturalzonehoodLUT.put(6.0, 20.0); // meters, Degrees
            neturalzonehoodLUT.put(7.5, 25.0); // meters, Degrees
        }
    }

    public class OppositeSideVelocityLUT{
        public static final InterpolatingDoubleTreeMap oppositesidevelocityLUT = new InterpolatingDoubleTreeMap();

        static{
            // 9-13 m is out of range for this shooter in the sim (needs > 42.5 rps)
            oppositesidevelocityLUT.put(7.0, 40.93); // meters, RPS
        }
    }

    public class OppositeSideHoodLUT{
        public static final InterpolatingDoubleTreeMap oppositesidehoodLUT = new InterpolatingDoubleTreeMap();

        static{
            // 9-13 m is out of range for this shooter in the sim (needs > 42.5 rps)
            oppositesidehoodLUT.put(7.0, 15.67); // meters, Degrees
        }
    }
}
